                      WAWebProtobufsE2E.PeerDataOperationRequestMessage.decode!(delimited)

                    previous_value ->
                      Protox.MergeMessage.merge(
                        previous_value,
                        WAWebProtobufsE2E.PeerDataOperationRequestMessage.decode!(delimited)
                      )
                  end
            }

            parse_key_value(rest, msg)

          <<"x", 0::1, varint_value::7, rest::binary>> ->
            value = varint_value
            msg = %{msg | timestampMS: value}
            parse_key_value(rest, msg)

          <<"x", bytes::binary>> ->
            {value, rest} = Protox.Decode.parse_int64(bytes)
            msg = %{msg | timestampMS: value}
            parse_key_value(rest, msg)

          <<"r", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)

            msg = %{
              msg
              | editedMessage:
                  case :erlang.map_get(:editedMessage, msg) do
                    nil ->
                      WAWebProtobufsE2E.Message.decode!(delimited)

                    previous_value ->
                      Protox.MergeMessage.merge(
                        previous_value,
                        WAWebProtobufsE2E.Message.decode!(delimited)
                      )
                  end
            }

            parse_key_value(rest, msg)

          <<"Z", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)

            msg = %{
              msg
              | disappearingMode:
                  case :erlang.map_get(:disappearingMode, msg) do
                    nil ->
                      WAWebProtobufsE2E.DisappearingMode.decode!(delimited)

                    previous_value ->
                      Protox.MergeMessage.merge(
                        previous_value,
                        WAWebProtobufsE2E.DisappearingMode.decode!(delimited)
                      )
                  end
            }

            parse_key_value(rest, msg)

          <<"R", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)

            msg = %{
              msg
              | appStateFatalExceptionNotification:
                  case :erlang.map_get(:appStateFatalExceptionNotification, msg) do
                    nil ->
                      WAWebProtobufsE2E.AppStateFatalExceptionNotification.decode!(delimited)

                    previous_value ->
                      Protox.MergeMessage.merge(
                        previous_value,
                        WAWebProtobufsE2E.AppStateFatalExceptionNotification.decode!(delimited)
                      )
                  end
            }

            parse_key_value(rest, msg)

          <<"J", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)

            msg = %{
              msg
              | initialSecurityNotificationSettingSync:
                  case :erlang.map_get(:initialSecurityNotificationSettingSync, msg) do
                    nil ->
                      WAWebProtobufsE2E.InitialSecurityNotificationSettingSync.decode!(delimited)

                    previous_value ->
                      Protox.MergeMessage.merge(
                        previous_value,
                        WAWebProtobufsE2E.InitialSecurityNotificationSettingSync.decode!(
                          delimited
                        )
                      )
                  end
            }

            parse_key_value(rest, msg)

          <<"B", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)

            msg = %{
              msg
              | appStateSyncKeyRequest:
                  case :erlang.map_get(:appStateSyncKeyRequest, msg) do
                    nil ->
                      WAWebProtobufsE2E.AppStateSyncKeyRequest.decode!(delimited)

                    previous_value ->
                      Protox.MergeMessage.merge(
                        previous_value,
                        WAWebProtobufsE2E.AppStateSyncKeyRequest.decode!(delimited)
                      )
                  end
            }

            parse_key_value(rest, msg)

          <<":", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)

            msg = %{
              msg
              | appStateSyncKeyShare:
                  case :erlang.map_get(:appStateSyncKeyShare, msg) do
                    nil ->
                      WAWebProtobufsE2E.AppStateSyncKeyShare.decode!(delimited)

                    previous_value ->
                      Protox.MergeMessage.merge(
                        previous_value,
                        WAWebProtobufsE2E.AppStateSyncKeyShare.decode!(delimited)
                      )
                  end
            }

            parse_key_value(rest, msg)

          <<"2", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)

            msg = %{
              msg
              | historySyncNotification:
                  case :erlang.map_get(:historySyncNotification, msg) do
                    nil ->
                      WAWebProtobufsE2E.HistorySyncNotification.decode!(delimited)

                    previous_value ->
                      Protox.MergeMessage.merge(
                        previous_value,
                        WAWebProtobufsE2E.HistorySyncNotification.decode!(delimited)
                      )
                  end
            }

            parse_key_value(rest, msg)

          <<"(", 0::1, varint_value::7, rest::binary>> ->
            value = varint_value
            msg = %{msg | ephemeralSettingTimestamp: value}
            parse_key_value(rest, msg)

          <<"(", bytes::binary>> ->
            {value, rest} = Protox.Decode.parse_int64(bytes)
            msg = %{msg | ephemeralSettingTimestamp: value}
            parse_key_value(rest, msg)

          <<" ", 0::1, varint_value::7, rest::binary>> ->
            value = varint_value
            msg = %{msg | ephemeralExpiration: value}
            parse_key_value(rest, msg)

          <<" ", bytes::binary>> ->
            {value, rest} = Protox.Decode.parse_uint32(bytes)
            msg = %{msg | ephemeralExpiration: value}
            parse_key_value(rest, msg)

          <<"\x10", 0::1, varint_value::7, rest::binary>> ->
            value = WAWebProtobufsE2E.ProtocolMessage.Type.decode(varint_value)
            msg = %{msg | type: value}
            parse_key_value(rest, msg)

          <<"\x10", bytes::binary>> ->
            {value, rest} =
              Protox.Decode.parse_enum(bytes, WAWebProtobufsE2E.ProtocolMessage.Type)

            msg = %{msg | type: value}
            parse_key_value(rest, msg)

          <<"\n", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)

            msg = %{
              msg
              | key:
                  case :erlang.map_get(:key, msg) do
                    nil ->
                      WACommon.MessageKey.decode!(delimited)

                    previous_value ->
                      Protox.MergeMessage.merge(
                        previous_value,
                        WACommon.MessageKey.decode!(delimited)
                      )
                  end
            }

            parse_key_value(rest, msg)

          <<bytes::binary>> ->
            {tag, wire_type, rest} = Protox.Decode.parse_key(bytes)
            {value, rest} = Protox.Decode.parse_unknown(tag, wire_type, rest)
            msg = %{msg | __uf__: [value | :erlang.map_get(:__uf__, msg)]}
            parse_key_value(rest, msg)
        end
      end
    )
  )

  (
    @spec unknown_fields(struct()) :: [{non_neg_integer(), Protox.Types.tag(), binary()}]
    def unknown_fields(msg), do: msg.__uf__

    @spec unknown_fields_name() :: :__uf__
    def unknown_fields_name(), do: :__uf__

    @spec clear_unknown_fields(struct) :: struct
    def clear_unknown_fields(msg), do: struct!(msg, __uf__: [])
  )

  (
    @spec default(atom()) ::
            {:ok, Protox.Scalar.scalar_default_value_type()}
            | {:error, :no_such_field | :no_default_value}
    def default(field_name), do: Protox.MessageSchema.default(@schema, field_name)
  )
end
